/**
 * The kinds of icon the game itself can supply, which decides how a {@link GameIcon}'s id is turned
 * into a picture.
 */
@AllArgsConstructor
@Getter
public enum GameIconType
{
	/** Id is an item id, rendered through {@code ItemManager}. */
	ITEM("Item"),
	/** Id is a sprite archive id, loaded through {@code SpriteManager}. */
	PRAYER("Prayer"),
	/** Id is a sprite archive id, loaded through {@code SpriteManager}. */
	SKILL("Skill"),
	/** Id is a sprite archive id, loaded through {@code SpriteManager}. */
	SPELL("Spell");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

